-- Carga de clientes.csv y catalogo_estados.csv a las tablas raw.
-- Motivo: el Table Data Import Wizard leía mal la codificación UTF-8 (acentos dañados: 'MÃ©xico').
-- Los valores son copia exacta de los CSV originales (sin limpiar ni corregir nada); los archivos originales no se modifican.
-- Ejecutar DESPUÉS de 01_creacion_bd.sql. Se puede re-ejecutar: vacía las tablas antes de cargar.
SET NAMES utf8mb4;
USE u4_etl;

TRUNCATE TABLE raw_clientes;

-- INSERT IGNORE: la base usa utf8mb4_unicode_ci (no distingue mayúsculas ni acentos),
-- así que alias como 'nuevo león' y 'NUEVO LEÓN' son el mismo valor de llave primaria; los repetidos se omiten.
TRUNCATE TABLE catalogo_estados;

-- Verificación (esperado: 510 filas / 500 clientes únicos / 16 alias)
SELECT COUNT(*) AS filas, COUNT(DISTINCT id_cliente) AS clientes_unicos FROM raw_clientes;
SELECT COUNT(*) AS filas_catalogo FROM catalogo_estados;
SELECT * FROM catalogo_estados ORDER BY estado_canonico, alias;
